//! Generated files: deterministic rendering and the generated-file marker.
//!
//! The application hands over a typed document ([`ExportDoc`]); this module turns it
//! into bytes, always the same bytes for the same document, and owns the marker
//! that says the file is generated.
//!
//! # The marker
//!
//! | file | where the marker is |
//! |---|---|
//! | `map.json` | the first key of the object, `"generated": {"note": "generated by whyshelf; do not edit", "content": "sha256:…"}` |
//! | `status.md`, `changelog.md` | the first line, `<!-- generated by whyshelf; do not edit; content: sha256:… -->` |
//!
//! `content` is the `export` hash of the file **without its marker**, rendered
//! as described next. It says nothing about the events the file was built from, so
//! an event that does not touch the file does not change it, and the same content
//! is always the same file.
//!
//! # Deterministic rendering
//!
//! JSON is written by [`render_json`]: object keys in byte order (whatever the
//! feature set of `serde_json` is), two-space indentation, one line feed at the end.
//! Markdown is built from ordered collections only. To find out whether somebody
//! edited a file, [`split_marker`] takes the marker out (for JSON by reading the
//! file and rendering it again without the `generated` key by the same rule, for
//! Markdown by cutting the first line) and the application compares the hash of the
//! rest with the marker (`export_drift`).

use serde_json::Value;
use whyshelf_core::app::ports::{ExportDoc, ExportKind};
use whyshelf_core::domain::hash::ContentHash;

use crate::map_dto::MapV1;
use crate::status_md;

/// The words of the marker.
const NOTE: &str = "generated by whyshelf; do not edit";

const MARKDOWN_PREFIX: &str = "<!-- generated by whyshelf; do not edit; content: ";
const MARKDOWN_SUFFIX: &str = " -->";

/// Why a document could not be rendered.
#[derive(Debug, thiserror::Error)]
pub enum RenderError {
    /// The map or its schema could not be turned into JSON.
    #[error("cannot render the map as JSON")]
    Json(#[source] serde_json::Error),
}

/// The file name of a generated file inside a store directory.
pub fn file_name(kind: ExportKind) -> &'static str {
    match kind {
        ExportKind::Map => "map.json",
        ExportKind::Status => "status.md",
        ExportKind::Changelog => "changelog.md",
    }
}

/// Render JSON by the deterministic rule: keys in byte order, two-space
/// indentation, a line feed at the end.
pub fn render_json(value: &Value) -> String {
    let mut out = String::new();
    write_value(&mut out, value, 0);
    out.push('\n');
    out
}

fn indent(out: &mut String, depth: usize) {
    for _ in 0..depth {
        out.push_str("  ");
    }
}

fn write_value(out: &mut String, value: &Value, depth: usize) {
    match value {
        Value::Object(map) if !map.is_empty() => {
            let mut entries: Vec<(&String, &Value)> = map.iter().collect();
            entries.sort_by(|a, b| a.0.cmp(b.0));
            out.push_str("{\n");
            let last = entries.len() - 1;
            for (index, (key, item)) in entries.into_iter().enumerate() {
                indent(out, depth + 1);
                out.push_str(&Value::String(key.clone()).to_string());
                out.push_str(": ");
                write_value(out, item, depth + 1);
                out.push_str(if index == last { "\n" } else { ",\n" });
            }
            indent(out, depth);
            out.push('}');
        }
        Value::Array(items) if !items.is_empty() => {
            out.push_str("[\n");
            let last = items.len() - 1;
            for (index, item) in items.iter().enumerate() {
                indent(out, depth + 1);
                write_value(out, item, depth + 1);
                out.push_str(if index == last { "\n" } else { ",\n" });
            }
            indent(out, depth);
            out.push(']');
        }
        Value::Object(_) => out.push_str("{}"),
        Value::Array(_) => out.push_str("[]"),
        // Strings (escaped), numbers, booleans and null print as JSON already.
        other => out.push_str(&other.to_string()),
    }
}

/// The content of a generated file, rendered without its marker.
pub fn render_body(doc: &ExportDoc<'_>) -> Result<String, RenderError> {
    Ok(match doc {
        ExportDoc::Map(map) => {
            let value = serde_json::to_value(MapV1::of(map)).map_err(RenderError::Json)?;
            render_json(&value)
        }
        ExportDoc::Status(status) => status_md::render_status(status),
        ExportDoc::Changelog(changelog) => status_md::render_changelog(changelog),
    })
}

/// The file: the marker and the body.
pub fn with_marker(kind: ExportKind, body: &str) -> String {
    let hash = ContentHash::export(body.as_bytes());
    match kind {
        ExportKind::Map => {
            let marker = format!(
                "  \"generated\": {{\n    \"note\": \"{NOTE}\",\n    \"content\": \"{hash}\"\n  }}"
            );
            match body.strip_prefix("{\n") {
                Some(rest) => format!("{{\n{marker},\n{rest}"),
                None => format!("{{\n{marker}\n}}\n"),
            }
        }
        ExportKind::Status | ExportKind::Changelog => {
            format!("{MARKDOWN_PREFIX}{hash}{MARKDOWN_SUFFIX}\n{body}")
        }
    }
}

/// Take the marker out of a file: the hash it carries and the body without it.
///
/// `None` when the file has no marker or one that cannot be read.
pub fn split_marker(kind: ExportKind, file: &[u8]) -> Option<(ContentHash, String)> {
    match kind {
        ExportKind::Map => {
            let Value::Object(mut map) = serde_json::from_slice::<Value>(file).ok()? else {
                return None;
            };
            let marker = map.remove("generated")?;
            let hash = marker.get("content")?.as_str()?.parse().ok()?;
            Some((hash, render_json(&Value::Object(map))))
        }
        ExportKind::Status | ExportKind::Changelog => {
            let text = std::str::from_utf8(file).ok()?;
            let (first, body) = text.split_once('\n')?;
            let hash = first
                .strip_prefix(MARKDOWN_PREFIX)?
                .strip_suffix(MARKDOWN_SUFFIX)?
                .parse()
                .ok()?;
            Some((hash, body.to_owned()))
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn json_is_rendered_with_sorted_keys_two_space_indent_and_a_final_line_feed() {
        let value =
            json!({"b": [1, 2], "a": {"y": null, "x": true}, "c": [], "d": {}, "e": "q\"\n"});
        assert_eq!(
            render_json(&value),
            "{\n  \"a\": {\n    \"x\": true,\n    \"y\": null\n  },\n  \"b\": [\n    1,\n    2\n  ],\n  \"c\": [],\n  \"d\": {},\n  \"e\": \"q\\\"\\n\"\n}\n"
        );
    }

    #[test]
    fn rendered_json_reads_back_to_the_same_value() {
        let value = json!({"z": {"k": [1, {"b": 2, "a": 1}]}, "s": "é\u{1}"});
        let back: Value = serde_json::from_str(&render_json(&value)).unwrap();
        assert_eq!(back, value);
    }

    #[test]
    fn a_json_file_carries_its_marker_as_the_first_key() {
        let body = render_json(&json!({"entities": {}, "version": 1}));
        let file = with_marker(ExportKind::Map, &body);
        assert!(file.starts_with(
            "{\n  \"generated\": {\n    \"note\": \"generated by whyshelf; do not edit\",\n    \"content\": \"sha256:"
        ));
        let value: Value = serde_json::from_str(&file).unwrap();
        assert_eq!(value["version"], 1);
        let (hash, rest) = split_marker(ExportKind::Map, file.as_bytes()).unwrap();
        assert_eq!(rest, body);
        assert_eq!(hash, ContentHash::export(body.as_bytes()));
    }

    #[test]
    fn a_markdown_file_carries_its_marker_on_the_first_line() {
        let body = "# Title\n\ntext\n";
        let file = with_marker(ExportKind::Status, body);
        let (first, rest) = file.split_once('\n').unwrap();
        assert!(first.starts_with("<!-- generated by whyshelf; do not edit; content: sha256:"));
        assert!(first.ends_with(" -->"));
        assert_eq!(rest, body);
        let (hash, back) = split_marker(ExportKind::Status, file.as_bytes()).unwrap();
        assert_eq!(
            (hash, back.as_str()),
            (ContentHash::export(body.as_bytes()), body)
        );
    }

    #[test]
    fn a_file_without_a_readable_marker_is_unmarked() {
        assert!(split_marker(ExportKind::Map, b"{\"version\": 1}").is_none());
        assert!(split_marker(ExportKind::Map, b"not json").is_none());
        assert!(split_marker(ExportKind::Map, b"[]").is_none());
        assert!(
            split_marker(ExportKind::Map, b"{\"generated\": {\"content\": \"nope\"}}").is_none()
        );
        assert!(split_marker(ExportKind::Status, b"# Title\n").is_none());
        assert!(
            split_marker(
                ExportKind::Changelog,
                b"<!-- generated by whyshelf -->\nx\n"
            )
            .is_none()
        );
    }

    /// The golden vector: the body, its hash, and the file around it never change by accident.
    #[test]
    fn the_marker_is_the_export_hash_of_the_body() {
        let body = "{\n  \"entities\": {},\n  \"version\": 1\n}\n";
        let file = with_marker(ExportKind::Map, body);
        let hash = ContentHash::export(body.as_bytes());
        assert_eq!(
            file,
            format!(
                "{{\n  \"generated\": {{\n    \"note\": \"generated by whyshelf; do not edit\",\n    \"content\": \"{hash}\"\n  }},\n  \"entities\": {{}},\n  \"version\": 1\n}}\n"
            )
        );
    }
}
